const CONTEXT = "jaspic-gmail-oauth-v1";
const encoder = new TextEncoder();
const decoder = new TextDecoder();

export type GmailWebSession = {
  state: string;
  codeVerifier: string;
  issuedAt: number;
  expiresAt: number;
  ownerId?: string;
