+  // A real cleanup operation MUST use explicit, separately audited metadata.
+  return classifyEvidenceRetention({
+    schemaVersion: 1,
+    recordedAt: row.checked_at,
+    expiresAt: null,
+    notificationEvidenceLinked: false,
+    preservationHold: false,
+  }, now);
+}
+
+/** Aggregate a dry-run report only. No SQL, deletes, or updates. */
+export function summarizeEvidenceRetention(
+  rows: Array<{checked_at:string;diagnostic:unknown}>,
+  now: string,
