  if (!rows.length || rows.some(f => f.kind !== 'OBSERVATION' || timestamp(f.baseTime) !== time || (timestamp(f.capturedAt) ?? -Infinity) < time || (timestamp(f.capturedAt) ?? Infinity) > now || !['RAIN','NO_RAIN'].includes(f.status ?? ''))) return null;
