+ const c=classifyRainPixel(rgba);return c.status==='RAIN'?`雨色（${c.intensityClass==='LT_1'?'1mm/h未満':c.intensityClass==='1_TO_5'?'1〜5mm/h':c.intensityClass}）`:'未知色（判定保留）';
