 // Verify the encoding is reversible, including alpha and unknown colors.
 if(!Buffer.from(PNG.sync.read(Buffer.from(bytes)).data).equals(Buffer.from(cropped.rgba)))throw Error('CROP_NOT_LOSSLESS');
