 BEGIN PERFORM * FROM public.rain_image_runs; EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 IF NOT denied THEN RAISE EXCEPTION 'ANON_PROBE_LEAK'; END IF;
END $$;
