+            {pushChecking ? "確認中…" : "🔍 通知の登録状態を確認"}
+          </button>
+          {pushRegistrationStatus && <p role="status" style={{ color: "#eef5ff", fontSize: 14 }}>{pushRegistrationStatus}</p>}
+        </div>
