+      <h1 style={{ marginTop: 0, marginBottom: 8, fontSize: "clamp(42px, 12vw, 64px)", lineHeight: 1.05, letterSpacing: "-0.05em" }}>アメくる？</h1>
+      <p style={{ marginTop: 0, color: "#e3edf8", fontSize: 18 }}>{status}</p>
+
