+          <button onClick={() => void searchPlace()} disabled={placeBusy} style={{ padding: "12px 16px", fontSize: 16, borderRadius: 12, border: "1px solid rgba(255,255,255,.14)", background: "#37628d", color: "#eaf2ff", fontWeight: 700 }}>検索</button>
