      "20260101/14.areas.json": [area("14130", "神奈川県")],
    });
    const loader = createSupabaseN03AdministrativeAreaLoader(storage as any);

    const result = await loader([
      { code: "14", name: "神奈川県", bbox: [0, 0, 0, 0] },
