+  const totalDuplicatedBytes=values.reduce((sum,value)=>sum+value,0);
+  const largestTiles=[...tileBytes].sort((a,b)=>b[1]-a[1]).slice(0,10).map(([tile,bytes])=>({tile,bytes,polygonReferences:tileParts.get(tile)}));
