      const jobs = pending.map(j => ({ id: j.id, lease_token: `00000000-0000-4000-8000-${String(j.id).padStart(12, "0")}`, run_key: `sustained-${j.id}`, basetime: "20260930060000", validtime: "20260930060500", zoom: 10, tile_x: FINAL_STAGE_STRESS_TILES[j.code].x, tile_y: FINAL_STAGE_STRESS_TILES[j.code].y }));
