        <h2 style={{ marginBottom: 6 }}>見張る場所を登録</h2>
        <p style={{ marginTop: 0, color: "#666" }}>自宅や実家など、雨を見張ってほしい場所を選んでね。</p>
        <button onClick={previewCurrentPlace} disabled={placeBusy} style={{ padding: "12px 16px", fontSize: 16 }}>
