    }) as unknown as typeof fetch;

    const provider = new JmaPublicImageProvider(fetcher);
    const series = await provider.getForecastSeries(35.681236, 139.767125);

    expect(series.frames.map((f) => f.validTime)).toEqual([
      "20260920120500",
      "20260920121000",
      "20260920121500",
    ]);
  });

});

