import { readFileSync } from "node:fs";
import { PNG } from "pngjs";
import { describe, expect, it } from "vitest";
import { VERIFIED_JMA_PNG_PALETTE, findVerifiedIntensity } from "./pngPalette";
import { classifyRainPixel } from "./classifyPixel";

// Independently recorded from JMA's hrpns SVG and raw PNG on 2026-09-23.
const verified = [
  [242, 242, 255, "LT_1"],
  [160, 210, 255, "1_TO_5"],
  [33, 140, 255, "5_TO_10"],
  [0, 65, 255, "10_TO_20"],
  [255, 153, 0, "30_TO_50"],
  [255, 40, 0, "50_TO_80"],
  [180, 0, 104, "GTE_80"],
] as const;

describe("verified JMA PNG palette", () => {
  it("contains only explicitly evidence-gated current JMA mappings", () => {
    expect(VERIFIED_JMA_PNG_PALETTE).toHaveLength(7);
    expect(VERIFIED_JMA_PNG_PALETTE.every((entry) => entry.evidence === "CURRENT_JMA_ASSET")).toBe(true);
  });

  it.each(verified)("classifies raw RGB (%i,%i,%i) as %s", (r, g, b, band) => {
    expect(findVerifiedIntensity({ r, g, b, a: 255 })).toBe(band);
    expect(findVerifiedIntensity({ r, g, b, a: 191 })).toBeNull();
  });

  it.each([
    [250, 245, 0], // PNG yellow does not match the hrpns legend.
    [255, 245, 0], // Legend yellow is not corroborated by raw PNG pixels.
    [0, 170, 255], // AMeDAS rain10m circle, not hrpns.
    [255, 170, 0], // AMeDAS rain10m circle, not hrpns.
    [1, 2, 3],
  ])("keeps unsupported RGB (%i,%i,%i) UNKNOWN_PIXEL", (r, g, b) => {
    expect(classifyRainPixel({ r, g, b, a: 255 })).toEqual({ status: "UNKNOWN_PIXEL", intensityClass: null });
  });

  it("decodes corroborated colors from the archived native-zoom JMA PNG", () => {
    const png = PNG.sync.read(readFileSync("docs/evidence/jma-palette-2026-09-23/hrpns-20260923101500-10-891-411.png"));
    const colors = new Set<string>();
    let unresolvedYellow = 0;
    for (let i = 0; i < png.data.length; i += 4) {
      const [r, g, b, a] = png.data.subarray(i, i + 4);
      colors.add(`${r},${g},${b},${a}`);
      if (r === 250 && g === 245 && b === 0 && a === 255) {
        expect(classifyRainPixel({ r, g, b, a }).status).toBe("UNKNOWN_PIXEL");
        unresolvedYellow++;
      }
    }
    for (const [r, g, b] of verified) expect(colors.has(`${r},${g},${b},255`)).toBe(true);
    expect(unresolvedYellow).toBe(562);
  });
});

import type { RainIntensityClass, Rgba } from "../../types";

export interface VerifiedPaletteEntry {
  rgba: Rgba;
  intensityClass: RainIntensityClass;
  evidence: "CURRENT_JMA_ASSET";
}

// Evidence: docs/PNG_PALETTE_EVIDENCE.md (2026-09-23), hrpns legend + raw PNGs.
// 20_TO_30 is deliberately absent: SVG #FFF500 and PNG #FAF500 disagree.
// AMeDAS rain10m circle assets are not evidence for hrpns intensity.
export const VERIFIED_JMA_PNG_PALETTE: readonly VerifiedPaletteEntry[] = [
  { rgba: { r: 242, g: 242, b: 255, a: 255 }, intensityClass: "LT_1", evidence: "CURRENT_JMA_ASSET" },
  { rgba: { r: 160, g: 210, b: 255, a: 255 }, intensityClass: "1_TO_5", evidence: "CURRENT_JMA_ASSET" },
  { rgba: { r: 33, g: 140, b: 255, a: 255 }, intensityClass: "5_TO_10", evidence: "CURRENT_JMA_ASSET" },
  { rgba: { r: 0, g: 65, b: 255, a: 255 }, intensityClass: "10_TO_20", evidence: "CURRENT_JMA_ASSET" },
  { rgba: { r: 255, g: 153, b: 0, a: 255 }, intensityClass: "30_TO_50", evidence: "CURRENT_JMA_ASSET" },
  { rgba: { r: 255, g: 40, b: 0, a: 255 }, intensityClass: "50_TO_80", evidence: "CURRENT_JMA_ASSET" },
  { rgba: { r: 180, g: 0, b: 104, a: 255 }, intensityClass: "GTE_80", evidence: "CURRENT_JMA_ASSET" },
];

export function findVerifiedIntensity(rgba: Rgba): RainIntensityClass | null {
  return VERIFIED_JMA_PNG_PALETTE.find(
    (entry) =>
      entry.rgba.r === rgba.r &&
      entry.rgba.g === rgba.g &&
      entry.rgba.b === rgba.b &&
      entry.rgba.a === rgba.a,
  )?.intensityClass ?? null;
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { getSupabaseBrowserClient } from "../../lib/supabase/browser";
import { compactFeedbackHistory, filterFeedbackByTarget, filterHistoryAfterArchive, historyArchiveStorageKey, historyQuerySince, negativeFeedbackNeedsWait, parseFeedbackHash, revealFeedbackCard, selectFeedbackHistory, summarizeFeedbackObservations, toggleFeedbackCard, watchedPlaceLabel } from "../../lib/weather/rain/feedbackPhase1";
import { loadPhase1Feedback, loadPhase2ObservationTimes, savePhase1Feedback, type WeatherFeedbackAnswer } from "../../lib/weather/rain/feedbackPhase1Repository";
import { observationAsLocalInput, observationVsDeliveryLabel, observedTimeLabel, resolveFeedbackObservation, summarizeObservationTimeCoverage, type ObservationChoice, type WeatherObservation } from "../../lib/weather/rain/feedbackObservationTime";

type Delivery = {
  id: number;
  target_id: string;
  event_type: string;
  body: string;
  delivered_at: string;
};
type Answer = WeatherFeedbackAnswer;
type Option = readonly [Answer, string];

export const FEEDBACK_OPTIONS: Record<string, readonly Option[]> = {
  ACTIONABLE_RAIN_APPROACHING: [
    ["RAINED", "☔ 降った"], ["DID_NOT_RAIN", "☁️ 降らなかった"],
    ["ALREADY_RAINING", "🌧️ すでに降っていた"], ["UNKNOWN", "❓ わからない"],
  ],
  RAIN_APPROACHING: [
    ["RAINED", "☔ 降った"], ["DID_NOT_RAIN", "☁️ 降らなかった"],
    ["ALREADY_RAINING", "🌧️ すでに降っていた"], ["UNKNOWN", "❓ わからない"],
  ],
  RAIN_RETURNING: [
    ["RAINED", "☔ 降った"], ["DID_NOT_RAIN", "☁️ 降らなかった"],
    ["ALREADY_RAINING", "🌧️ すでに降っていた"], ["UNKNOWN", "❓ わからない"],
  ],
  RAIN_ENDING: [
    ["STOPPED", "☀️ 止んだ"], ["DID_NOT_STOP", "🌧️ 止まなかった"],
    ["ALREADY_DRY", "☁️ すでに降っていなかった"], ["UNKNOWN", "❓ わからない"],
  ],
};

// Phase 1 has no persisted forecast target time on legacy Push rows.
// Avoid presenting a negative outcome as verified immediately after delivery.
function formatTokyo(timestamp: string): string {
  return new Date(timestamp).toLocaleString("ja-JP", {
    timeZone: "Asia/Tokyo", month: "numeric", day: "numeric",
    hour: "2-digit", minute: "2-digit",
  });
}

export default function NotificationFeedbackHistory() {
  const [notifications, setNotifications] = useState<Delivery[]>([]);
  const [targetLabels, setTargetLabels] = useState<Record<string, string>>({});
  const [answers, setAnswers] = useState<Record<number, Answer>>({});
  const [observationTimes, setObservationTimes] = useState<Record<number,WeatherObservation>>({});
  const [observationChoices, setObservationChoices] = useState<Record<number,ObservationChoice>>({});
  const [earlierInputs, setEarlierInputs] = useState<Record<number,string>>({});
  const [feedbackReady, setFeedbackReady] = useState(false);
  const [message, setMessage] = useState("通知履歴を読み込み中…");
  const [saving, setSaving] = useState<number | null>(null);
  const [saved, setSaved] = useState<number | null>(null);
  const [filter, setFilter] = useState<"all" | "unanswered" | "answered">("all");
  const [selectedTargetId, setSelectedTargetId] = useState("all");
  const [shownCount, setShownCount] = useState(2);
  const [expandedIds, setExpandedIds] = useState<number[]>([]);
  const [focusedNotificationId, setFocusedNotificationId] = useState<number | null>(null);
  const [ownerId, setOwnerId] = useState<string | null>(null);
  const [archivedThrough, setArchivedThrough] = useState<string | null>(null);
  const [showArchived, setShowArchived] = useState(false);
  const [archiveMessage, setArchiveMessage] = useState("");

  const refresh = useCallback(async () => {
    if (!process.env.NEXT_PUBLIC_SUPABASE_URL || !process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY) {
      setMessage("この検証画面では通知履歴を利用できないよ。");
      setNotifications([]);
      setOwnerId(null);
      setArchivedThrough(null);
      setTargetLabels({});
      setFeedbackReady(false);
      setAnswers({});
      setObservationTimes({});
      setObservationChoices({});
      setEarlierInputs({});
      return;
    }
    try {
      const client = getSupabaseBrowserClient();
      const { data: { session }, error: authError } = await client.auth.getSession();
      if (authError) throw authError;
      if (!session) {
        setOwnerId(null);
        setArchivedThrough(null);
        setShowArchived(false);
        setNotifications([]);
        setTargetLabels({});
        setAnswers({});
        setObservationTimes({});
        setObservationChoices({});
        setEarlierInputs({});
        setFeedbackReady(false);
        setMessage("この通知を受け取った端末・アカウントで開いてね。");
        return;
      }
      // UI-only archive boundary: stored in this device's browser storage.
      // The DB and Push notification pipeline are never changed.
      if (ownerId !== session.user.id) {
        setOwnerId(session.user.id);
        setShowArchived(false);
      }
      try {
        const stored = window.localStorage.getItem(historyArchiveStorageKey(session.user.id));
        setArchivedThrough(stored && Number.isFinite(Date.parse(stored)) ? stored : null);
      } catch {
        setArchivedThrough(null);
      }
      // A Push deep link may target a delivery older than seven days.
      // Include older rows while a focused notification is requested;
      // the existing archive boundary and focused-card logic still apply.
      const focusedFromUrl = typeof window !== "undefined"
        ? parseFeedbackHash(window.location.hash) : null;
      const since = historyQuerySince(showArchived || focusedFromUrl !== null, Date.now());
      let deliveryQuery = client.from("notification_deliveries")
        .select("id,target_id,event_type,body,delivered_at")
        .gt("delivered_count", 0);
      if (since) deliveryQuery = deliveryQuery.gte("delivered_at", since);
      const { data, error } = await deliveryQuery
        .order("delivered_at", { ascending: false })
        .limit(200);
      if (error) throw error;
      const rows = (data ?? []) as Delivery[];
      setNotifications(rows);
      // Historical answers must always be described using the registered
      // watched place; device location and target location may be different.
      const ids = [...new Set(rows.map(row => row.target_id))];
      if (ids.length) {
        const { data: targets, error: targetError } = await client
          .from("watch_targets").select("id,label").in("id", ids);
        setTargetLabels(!targetError ? Object.fromEntries(
          (targets ?? []).map(target => [target.id, String(target.label ?? "")]),
        ) : {});
      } else {
        setTargetLabels({});
      }
      if (rows.length === 0) {
        setAnswers({});
        setObservationTimes({});
        setFeedbackReady(false);
        setMessage("表示できる通知はまだないよ。");
        return;
      }
      try {
        const recorded = await loadPhase1Feedback(client, rows.map(row => row.id));
        const times = await loadPhase2ObservationTimes(client, rows.map(row => row.id));
        setAnswers(recorded);
        setObservationTimes(times);
        setFeedbackReady(true);
        setMessage("");
      } catch {
        setAnswers({});
        setObservationTimes({});
        setFeedbackReady(false);
        setMessage("通知履歴は表示できるよ。回答機能はまだ準備中だよ。");
      }
    } catch {
      setNotifications([]);
      setTargetLabels({});
      setAnswers({});
      setObservationTimes({});
      setFeedbackReady(false);
      setMessage("通知履歴を読み込めなかったよ。少しあとでもう一度試してね。");
    }
  }, [ownerId, showArchived]);

  useEffect(() => {
    void refresh();
    const interval = window.setInterval(() => void refresh(), 5 * 60 * 1000);
    const onVisible = () => { if (document.visibilityState === "visible") void refresh(); };
    document.addEventListener("visibilitychange", onVisible);

    // The user may register a watched place (anonymous Supabase sign-in)
    // without leaving this page. Refresh feedback immediately after sign-in.
    // Never call Supabase async APIs inside onAuthStateChange itself.
    // Same-tab registration may use a separate Supabase client instance.
    // The registration flow emits this event after a new anonymous session.
    const onRegistered = () => void refresh();
    window.addEventListener("amefuru:auth-ready", onRegistered);

    // Subscribe only in configured environments. Supabase callbacks are
    // synchronous: defer refresh instead of invoking async auth methods inside.
    let pendingAuthRefresh: number | null = null;
    const subscription = (process.env.NEXT_PUBLIC_SUPABASE_URL &&
      process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY)
      ? getSupabaseBrowserClient().auth.onAuthStateChange((event) => {
        if (event !== "SIGNED_IN" && event !== "SIGNED_OUT") return;
        if (pendingAuthRefresh !== null) window.clearTimeout(pendingAuthRefresh);
        pendingAuthRefresh = window.setTimeout(() => {
          pendingAuthRefresh = null;
          void refresh();
        }, 0);
      }).data.subscription : null;
    return () => {
      window.clearInterval(interval);
      document.removeEventListener("visibilitychange", onVisible);
      window.removeEventListener("amefuru:auth-ready", onRegistered);
      if (pendingAuthRefresh !== null) window.clearTimeout(pendingAuthRefresh);
      subscription?.unsubscribe();
    };
  }, [refresh]);

  // Phase 1: links from today's alerts work without changing the Push payload.
  useEffect(() => {
    const readHash = () => {
      const focused = parseFeedbackHash(window.location.hash);
      setFocusedNotificationId(focused);
      if (focused !== null) setExpandedIds(previous => revealFeedbackCard(previous, focused));
      if (focused !== null) {
        // A link from today's alert should work even after choosing a
        // different location in the history filter.
        setSelectedTargetId("all");
      }
    };
    readHash();
    window.addEventListener("hashchange", readHash);
    return () => window.removeEventListener("hashchange", readHash);
  }, []);

  useEffect(() => {
    if (focusedNotificationId === null || !notifications.some(n => n.id === focusedNotificationId)) return;
    document.getElementById(`rain-feedback-${focusedNotificationId}`)
      ?.scrollIntoView({ block: "start", behavior: "smooth" });
  }, [focusedNotificationId, notifications, filter]);

  const save = async (notification: Delivery, answer: Answer) => {
    const allowed = FEEDBACK_OPTIONS[notification.event_type];
    if (!feedbackReady || !allowed?.some(([value]) => value === answer)) return;
    if (negativeFeedbackNeedsWait(answer, notification.delivered_at, Date.now())) {
      setMessage("「降らなかった」「止まなかった」は、通知から1時間以上たってから回答してね。");
      return;
    }
    let observation:WeatherObservation;
    try {
      observation = resolveFeedbackObservation(
        observationChoices[notification.id], observationTimes[notification.id],
        earlierInputs[notification.id], new Date(),
      );
    } catch {
      setMessage("確認時刻を確認してね。未来の時刻や30日以上前は指定できないよ。");
      return;
    }
    setSaving(notification.id);
    setSaved(null);
    setMessage("");
    try {
      const client = getSupabaseBrowserClient();
      await savePhase1Feedback(client, notification.id, answer, observation);
      setAnswers(prev => ({ ...prev, [notification.id]: answer }));
      setObservationTimes(prev => ({...prev,[notification.id]:observation}));
      setObservationChoices(prev=>{const next={...prev};delete next[notification.id];return next;});
      setSaved(notification.id);
    } catch {
      setMessage("回答を保存できなかったよ。少しあとでもう一度試してね。");
    } finally {
      setSaving(null);
    }
  };

  const archivedCount = archivedThrough
    ? notifications.filter(n=>Date.parse(n.delivered_at)<=Date.parse(archivedThrough)).length : 0;
  // Hash links to earlier notifications must still work after archiving.
  const linkedArchived = focusedNotificationId !== null && notifications.some(n=>
    n.id===focusedNotificationId && archivedThrough !== null &&
    Date.parse(n.delivered_at)<=Date.parse(archivedThrough));
  const historyNotifications = filterHistoryAfterArchive(
    notifications,archivedThrough,showArchived || linkedArchived);
  const selectedNotifications = filterFeedbackByTarget(historyNotifications, selectedTargetId);
  const resetVisibleHistory = () => {
    if (!ownerId || saving !== null) return;
    const boundary=new Date().toISOString();
    try {
      window.localStorage.setItem(historyArchiveStorageKey(ownerId),boundary);
    } catch {
      setArchiveMessage("この端末に整理設定を保存できなかったよ。ブラウザの保存設定を確認してね。");
      return;
    }
    setArchivedThrough(boundary);
    setShowArchived(false);
    setShownCount(2);
    setExpandedIds([]);
    setFilter("all");
    setSelectedTargetId("all");
    setArchiveMessage("ここまでの通知を画面から整理したよ。DBの通知と回答はそのまま保存されているよ。");
    if (window.location.hash.startsWith("#rain-feedback-")) {
      window.history.replaceState(null,"",window.location.pathname+window.location.search);
      setFocusedNotificationId(null);
    }
  };
  const history = selectFeedbackHistory(selectedNotifications, answers,
    new Set(Object.keys(FEEDBACK_OPTIONS)), filter, focusedNotificationId);
  const { visible, unanswered } = history;
  const observations = summarizeFeedbackObservations(selectedNotifications, answers);
  const compactHistory = compactFeedbackHistory(visible, shownCount, focusedNotificationId);
  const targetIds = [...new Set(notifications.map(n => n.target_id))];
  const timingCoverage = summarizeObservationTimeCoverage(selectedNotifications.map(n=>n.id),answers,observationTimes);

  return (
    <section style={{ margin: "28px 0", padding: 20, border: "1px solid rgba(255,255,255,.15)", borderRadius: 20, background: "rgba(24,55,88,.8)" }}>
      <h2 style={{ marginTop: 0, marginBottom: 6 }}>🌧️ 届いた通知の天気を教えてね</h2>
      <p style={{ marginTop: 0, fontSize: 14, color: "#eef5ff" }}>
        直近2件を表示しているよ。通知をタップすると回答できるよ。
        見ていない場所なら「わからない」で大丈夫だよ。
      </p>
      {message && <p role="status" style={{ color: "#ffe1a0" }}>{message}</p>}
      {ownerId && feedbackReady && (
        <div style={{margin:"12px 0",padding:"10px 12px",border:"1px solid rgba(125,211,252,.35)",borderRadius:12}}>
          <div style={{fontSize:13,color:"#eef5ff",marginBottom:8}}>
            🗂️ 過去の通知はDBに保管したまま、画面だけ新しい記録から始められるよ。
            この整理設定はこの端末・ブラウザのアカウント別に保存されるよ。
          </div>
          <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
            <button type="button" onClick={resetVisibleHistory} disabled={saving!==null}
              style={{padding:"8px 12px",borderRadius:10,color:"#fff",background:"#28567e",
                border:"1px solid #7dd3fc",cursor:"pointer"}}>
              🗂️ ここまでの通知を画面から整理
            </button>
            {archivedThrough && (
              <button type="button" onClick={()=>{setShowArchived(x=>!x);setShownCount(2);}}
                aria-pressed={showArchived}
                style={{padding:"8px 12px",borderRadius:10,color:"#fff",
                  background:"#284e75",border:"1px solid #7799b8",cursor:"pointer"}}>
                {showArchived?"新しい通知だけに戻す":"過去の通知を見る（最大200件）"}
              </button>
